import java.io.*;
import java.util.Scanner;

public class MagneticField {
    public static void main(String[] args) throws IOException {
       Scanner input = new Scanner(System.in);
       System.out.print("Enter the number of rows in the table: ");
       int rows = input.nextInt();
       System.out.print("Enter the number of columns in the table: ");
       int cols = input.nextInt();
       String[][] matrix = new String[rows][cols];
       for (int i = 0; i < rows; i++) {
          System.out.print("Enter row " + (i+1) + ": ");
          String line = input.nextLine();
          String[] line_array = line.split(",");
          for (int j = 0; j < cols; j++) {
            matrix[i][j] = line_array[j];
          }
       }

       double intensity_sum = 0.0;
       for (int i = 0; i < rows; i++) {
         for (int j = 0; j < cols; j++) {
             intensity_sum += Double.parseDouble(matrix[i][j]);
         }
       }
       System.out.println("The average intensity was " + intensity_sum / rows);

