response:
 Yes, this is certainly possible to implement using Python. Here is one possible approach:

# Imports
import json
from math import sqrt

# Create dictionary of car sizes
car_sizes = {
    'compact': {'name': 'Compact', 'heightRange': '4'6"-5'2"}
    ,'midsize': {'name': 'Midsize', 'heightRange': '5'3"-5'5'}
    ,'fullsize': {'name': 'Fullsize', 'heightRange': '5'6"-5'9'}
    ,'luxury': {'name': 'Luxury', 'heightRange': '5'10"-6'1'}
    ,'suv': {'name': 'SUV', 'heightRange': '6'2"-6'4'}
    ,'truck': {'name': 'Truck', 'heightRange': '6'5"-6'7'}
    ,'van': {'name': 'Van', 'heightRange': '6'8" and up'}
}

# Parse JSON data
with open('jsonData') as file:
    data = json.load(file)

# Calculate car size recommendation
def calculateCarSizeRecommendation(customerHeight):
    # Get average car length for each car size
    carLengthsByCarType = dict()
    for carType in car_sizes.keys():
        carLengthsByCarType[carType] = sqrt(data['carSizes'][carType]['length']/data['carSizes'][carType]['heightRange'])

    # Calculate car size recommendation
    if customerHeight < carLengthsByCarType['compact']:
        return 'compact'
    elif customerHeight < carLengthsByCarType['midsize']:
        return 'midsize'
    else:
        return 'fullsize'

