Here’s some example code from the Accord.NET library, demonstrating how to train and apply the Naive Bayes classifier:  

public static void NaiveBayesTraining() {
    // Load training data as a dictionary of strings to labels, where keys are words and values are labels
    var trainingData = new Dictionary<string, string>();
    trainingData.Add("football", "Sports");
    trainingData.Add("politics", "Politics");
    trainingData.Add("entertainment", "Entertainment");

    // Create the Naive Bayes classifier
    var naiveBayesClassifier = new NaiveBayesClassifier(trainingData);

    // Compute the conditional probabilities of each word in the training data given each category
    var wordProbabilityMatrix = naiveBayesClassifier.GetWordProbabilities();

    // Apply the Naive Bayes classifier to classify a new observation
    var prediction = naiveBayesClassifier.Predict("The sports game was exciting");
}

